//! AIA chain-reassembly integration tests for `Verifier::verify_one`.
//!
//! Covers the `PKIX-zkjb.7` chain-build wiring: when the caller-supplied
//! chain is incomplete and a real [`AiaFetcher`](pkix_aia::AiaFetcher) is
//! configured, the verifier follows `id-ad-caIssuers` URIs to fetch the
//! missing intermediate, augments the path-builder pool, and reassembles
//! the chain. `NoAiaFetcher` short-circuits with `AiaError::FetchingDisabled`.
//!
//! Fixtures (generated by `tests/fixtures/gen.py`):
//!
//! - `root.der` — P-256 self-signed CA; anchor for every chain here.
//! - `intermediate.der` — P-256 CA signed by `root.der`. Returned by the
//!   in-process fetcher when the caller-supplied chain omits it.
//! - `leaf-via-intermediate.der` — P-256 EE signed by `intermediate.der`
//!   with `id-ad-caIssuers` URI `http://example.test/intermediate.der`.
//! - `leaf-via-intermediate-no-aia.der` — same shape but no AIA extension,
//!   for the "no URIs to follow" negative case.

use std::collections::HashMap;
use std::sync::Mutex;

use pkix_aia::{AiaError, AiaFetcher};
use pkix_chain::{verify_chain, DefaultVerifier, NoAiaFetcher, NoRevocation, Verifier};
use pkix_path::{TrustAnchor, ValidationPolicy};
use x509_cert::der::Decode as _;
use x509_cert::Certificate;

const ROOT_DER: &[u8] = include_bytes!("fixtures/root.der");
const INTERMEDIATE_DER: &[u8] = include_bytes!("fixtures/intermediate.der");
const LEAF_VIA_INTERMEDIATE_DER: &[u8] = include_bytes!("fixtures/leaf-via-intermediate.der");
const LEAF_VIA_INTERMEDIATE_NO_AIA_DER: &[u8] =
    include_bytes!("fixtures/leaf-via-intermediate-no-aia.der");

/// Gen.py uses validity range 2000-01-01 to 2050-01-01 UTC. 2020-01-01 is
/// safely inside. Matches the other pkix-chain test files.
const NOW_UNIX: u64 = 1_577_836_800;

fn load(der: &[u8]) -> Certificate {
    Certificate::from_der(der).expect("parse cert")
}

/// In-process `AiaFetcher` backed by a URI → DER map. Records every URI
/// fetched so tests can assert which intermediates were pulled.
///
/// Defined here rather than as a public surface in `pkix-chain` because
/// the fake is test-infrastructure, not part of the crate's API. Real
/// HTTP fetchers live in `pkix-aia-http`; this stub exists only to drive
/// the integration test without binding to a transport.
struct MockAiaFetcher {
    responses: HashMap<String, Vec<u8>>,
    fetched: Mutex<Vec<String>>,
}

impl MockAiaFetcher {
    fn new<I: IntoIterator<Item = (String, Vec<u8>)>>(entries: I) -> Self {
        Self {
            responses: entries.into_iter().collect(),
            fetched: Mutex::new(Vec::new()),
        }
    }

    fn fetched_uris(&self) -> Vec<String> {
        self.fetched.lock().expect("mutex poisoned").clone()
    }
}

impl AiaFetcher for MockAiaFetcher {
    fn fetch(&self, uri: &str) -> Result<Vec<u8>, AiaError> {
        self.fetched
            .lock()
            .expect("mutex poisoned")
            .push(uri.to_owned());
        match self.responses.get(uri) {
            Some(der) => Ok(der.clone()),
            None => Err(AiaError::HttpStatus(404)),
        }
    }
}

/// Happy path: chain = [leaf] only (no intermediate, no anchor cert).
/// `MockAiaFetcher` returns the missing intermediate when asked for the
/// `caIssuers` URI baked into the leaf's AIA extension. The verifier
/// must succeed and the reassembled chain must include the intermediate.
#[test]
fn aia_fetches_missing_intermediate_and_chain_validates() {
    let leaf = load(LEAF_VIA_INTERMEDIATE_DER);
    let chain = [leaf];
    let anchors = [TrustAnchor::from_cert(load(ROOT_DER))];
    let policy = ValidationPolicy::new(NOW_UNIX);

    let fetcher = MockAiaFetcher::new([(
        "http://example.test/intermediate.der".to_owned(),
        INTERMEDIATE_DER.to_vec(),
    )]);

    let verifier = Verifier::new(&anchors, &DefaultVerifier, &NoRevocation, &policy, &fetcher);
    let result = verifier.verify_one(&chain);
    let validated = result.expect("AIA-augmented build should succeed");

    assert_eq!(validated.anchor_index, 0, "single anchor at index 0");
    assert_eq!(
        validated.depth, 1,
        "one fetched intermediate sits between leaf and anchor"
    );

    let fetched = fetcher.fetched_uris();
    assert_eq!(
        fetched.as_slice(),
        &["http://example.test/intermediate.der".to_owned()],
        "exactly the AIA URI from the leaf was visited",
    );
}

/// Same chain shape as above but with `NoAiaFetcher`. The verifier must
/// fail with `Error::Aia(AiaError::FetchingDisabled)` — no panic, no I/O,
/// no recursion.
#[test]
fn no_aia_fetcher_fails_cleanly_on_missing_intermediate() {
    let leaf = load(LEAF_VIA_INTERMEDIATE_DER);
    let chain = [leaf];
    let anchors = [TrustAnchor::from_cert(load(ROOT_DER))];
    let policy = ValidationPolicy::new(NOW_UNIX);

    let result = verify_chain(
        &chain,
        &anchors,
        &policy,
        &DefaultVerifier,
        &NoRevocation,
        &NoAiaFetcher,
    );

    let err = result.expect_err("NoAiaFetcher must fail on a missing intermediate");
    assert!(
        matches!(err, pkix_chain::Error::Aia(AiaError::FetchingDisabled)),
        "expected Error::Aia(FetchingDisabled), got: {err:?}"
    );
}

/// Leaf has no AIA extension. With any fetcher (even one that would have
/// answered), there is no URI to follow, so the verifier must surface a
/// path-build failure rather than panicking or looping. We use
/// `NoAiaFetcher` here because the absence of URIs is the salient
/// property — what fetcher would have answered is irrelevant.
#[test]
fn missing_intermediate_with_no_aia_uri_surfaces_path_build_error() {
    let leaf = load(LEAF_VIA_INTERMEDIATE_NO_AIA_DER);
    let chain = [leaf];
    let anchors = [TrustAnchor::from_cert(load(ROOT_DER))];
    let policy = ValidationPolicy::new(NOW_UNIX);

    let result = verify_chain(
        &chain,
        &anchors,
        &policy,
        &DefaultVerifier,
        &NoRevocation,
        &NoAiaFetcher,
    );

    let err = result.expect_err("must fail without an intermediate and no AIA URI");
    assert!(
        matches!(
            err,
            pkix_chain::Error::PathBuild(pkix_path_builder::Error::NoPathFound)
        ),
        "expected PathBuild(NoPathFound), got: {err:?}"
    );
}

/// Caller supplies the complete chain `[leaf, intermediate]`. The fast
/// path should validate directly without consulting the AIA fetcher.
/// We attach a `MockAiaFetcher` with no entries and assert it was never
/// invoked.
#[test]
fn complete_chain_skips_aia_fast_path() {
    let leaf = load(LEAF_VIA_INTERMEDIATE_DER);
    let intermediate = load(INTERMEDIATE_DER);
    let chain = [leaf, intermediate];
    let anchors = [TrustAnchor::from_cert(load(ROOT_DER))];
    let policy = ValidationPolicy::new(NOW_UNIX);

    let fetcher = MockAiaFetcher::new(std::iter::empty());

    let verifier = Verifier::new(&anchors, &DefaultVerifier, &NoRevocation, &policy, &fetcher);
    let validated = verifier
        .verify_one(&chain)
        .expect("complete chain validates directly");

    assert_eq!(
        validated.depth, 1,
        "one intermediate in the validated chain"
    );
    assert!(
        fetcher.fetched_uris().is_empty(),
        "AIA fetcher must not be invoked when the supplied chain is complete; got fetches: {:?}",
        fetcher.fetched_uris(),
    );
}

/// A complete chain whose leaf is expired must surface `Path(ValidityPeriod)`
/// directly — AIA fetching cannot repair a cert-correctness failure and
/// must not be attempted. Uses `now_unix = 0` which is before every
/// fixture's `notBefore` (gen.py uses 2000-01-01).
#[test]
fn non_recoverable_path_error_does_not_invoke_aia() {
    let leaf = load(LEAF_VIA_INTERMEDIATE_DER);
    let intermediate = load(INTERMEDIATE_DER);
    let chain = [leaf, intermediate];
    let anchors = [TrustAnchor::from_cert(load(ROOT_DER))];
    let policy = ValidationPolicy::new(0); // before notBefore

    let fetcher = MockAiaFetcher::new([(
        "http://example.test/intermediate.der".to_owned(),
        INTERMEDIATE_DER.to_vec(),
    )]);

    let verifier = Verifier::new(&anchors, &DefaultVerifier, &NoRevocation, &policy, &fetcher);
    let err = verifier
        .verify_one(&chain)
        .expect_err("expired cert must surface a path error");

    assert!(
        matches!(
            err,
            pkix_chain::Error::Path(pkix_path::Error::ValidityPeriod { .. })
        ),
        "expected Path(ValidityPeriod), got: {err:?}"
    );
    assert!(
        fetcher.fetched_uris().is_empty(),
        "non-recoverable path errors must not invoke AIA; got fetches: {:?}",
        fetcher.fetched_uris(),
    );
}

/// Leaf has an AIA URI but the fetcher returns 404 for it. The verifier
/// must surface `Error::Aia(HttpStatus(404))` — the most recent fetch
/// failure — rather than `FetchingDisabled` (the fetch *was* attempted)
/// or `PathBuild(NoPathFound)` (we did extract URIs and tried).
#[test]
fn aia_fetch_failure_surfaces_underlying_error() {
    let leaf = load(LEAF_VIA_INTERMEDIATE_DER);
    let chain = [leaf];
    let anchors = [TrustAnchor::from_cert(load(ROOT_DER))];
    let policy = ValidationPolicy::new(NOW_UNIX);

    // Fetcher with NO mapping for the AIA URI — the default arm returns
    // AiaError::HttpStatus(404).
    let fetcher = MockAiaFetcher::new(std::iter::empty());

    let verifier = Verifier::new(&anchors, &DefaultVerifier, &NoRevocation, &policy, &fetcher);
    let err = verifier
        .verify_one(&chain)
        .expect_err("404 on the AIA URI must surface");
    assert!(
        matches!(err, pkix_chain::Error::Aia(AiaError::HttpStatus(404))),
        "expected Aia(HttpStatus(404)), got: {err:?}"
    );

    let fetched = fetcher.fetched_uris();
    assert_eq!(fetched.len(), 1, "exactly one fetch attempt: {fetched:?}");
}

/// Fetcher returns garbage bytes for the AIA URI. The verifier must
/// surface `Error::Aia(MalformedCertificate(diag))` after exhausting fetch
/// attempts — proving that response-parse failures are captured (with the
/// DER parse diagnostic, not the URI) rather than silently dropped.
#[test]
fn aia_fetch_returns_garbage_surfaces_malformed_certificate() {
    let leaf = load(LEAF_VIA_INTERMEDIATE_DER);
    let chain = [leaf];
    let anchors = [TrustAnchor::from_cert(load(ROOT_DER))];
    let policy = ValidationPolicy::new(NOW_UNIX);

    let fetcher = MockAiaFetcher::new([(
        "http://example.test/intermediate.der".to_owned(),
        vec![0xff, 0xff, 0xff, 0xff], // not a Certificate
    )]);

    let verifier = Verifier::new(&anchors, &DefaultVerifier, &NoRevocation, &policy, &fetcher);
    let err = verifier
        .verify_one(&chain)
        .expect_err("garbage AIA response must surface");
    match err {
        pkix_chain::Error::Aia(AiaError::MalformedCertificate(diag)) => {
            // The inner string must be a DER parse diagnostic, not a URI.
            assert!(!diag.is_empty(), "diagnostic must not be empty");
            assert!(
                !diag.starts_with("http://"),
                "diagnostic must be a parse error, not a URI: {diag}",
            );
        }
        other => panic!("expected Aia(MalformedCertificate), got: {other:?}"),
    }
}
